# Adds the Swift files (store + MIDI plugin + the first screen) to the generated Xcode project (ios/ is generated by `cap add ios`, so this runs on every build).
# Usage: ruby add-to-project.rb <path to App.xcodeproj>   (the .swift files must already be in ios/App/App/)
require 'xcodeproj'
proj = Xcodeproj::Project.open(ARGV[0])
target = proj.targets.find { |t| t.name == 'App' } or abort 'target App not found'
group = proj.main_group['App'] or abort 'group App not found'
%w[PianistStorePlugin.swift PianistMidiPlugin.swift MainViewController.swift].each do |f|
  next if group.files.any? { |x| x.path == f }
  target.add_file_references([group.new_reference(f)])
end
# the MIDI plugin
%w[CoreMIDI CoreAudioKit].each { |f| begin; target.add_system_framework(f); rescue => e; warn "framework #{f}: #{e}"; end }
# StoreKit 2 needs iOS 15
target.build_configurations.each { |c| c.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '15.0' }
proj.save
puts "store plugin added to #{ARGV[0]}"
